#include <stdio.h>
#include <stdlib.h>
#include <time.h>

int main () {
    unsigned user_number, computer_number, choice, result = 0;
    srand(time(0));
    computer_number = rand() % 10 + 1;
    //The game will work as follows: the computer will generate a number
    //from 1 to 10, and you will also enter a number. Before adding your
    // number, you must guess whether your number will be greater than,
    // less than, or equal to the number generated by the computer.

    printf("Choose one of the following options\n");
    printf("1: Your number will be higher\n");
    printf("2: Your number will be smaller\n");
    printf("3: Your number will be equal\n");
    scanf("%u", &choice);
    printf("Enter your number it should be in the range of 1 to 10:\n");
    scanf("%u", &user_number);

    switch (choice)
    {
    case 1:
        result = (user_number > computer_number);
        break;
    case 2:
        result = (user_number < computer_number);
        break;
    case 3:
        result = (user_number == computer_number);
        break;
    default:
        printf("ERRO!! Invalid value");
        return 1;
    }

    if (result == 1) {
        printf("Congratulation!! You wins, you got the number right.\n User number: %u\n Computer number: %u\n", user_number, computer_number);
    }else {
        printf("unfortunately you made a mistake.\n User number: %u\n Computer number: %u\n", user_number, computer_number);
    }
    return 0;
}